-- Stop the target zone, back up and capture fresh preimages before applying.
DELIMITER //
BEGIN NOT ATOMIC
DECLARE n BIGINT;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
START TRANSACTION;
SELECT COUNT(*) INTO n FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='nightcap_dungeon_spawns' AND ENGINE='InnoDB';
IF n<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Hate layout engine drift: nightcap_dungeon_spawns'; END IF;
SELECT COUNT(*) INTO n FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='nightcap_dungeon_spawns';
IF n<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Hate layout trigger drift: nightcap_dungeon_spawns'; END IF;
SELECT COUNT(*) INTO n FROM `nightcap_dungeon_spawns` WHERE zone_id=186 FOR UPDATE;
IF n<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Hate layout count drift: nightcap_dungeon_spawns'; END IF;
SELECT COUNT(*) INTO n FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='grid' AND ENGINE='InnoDB';
IF n<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Hate layout engine drift: grid'; END IF;
SELECT COUNT(*) INTO n FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='grid';
IF n<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Hate layout trigger drift: grid'; END IF;
SELECT COUNT(*) INTO n FROM `grid` WHERE zoneid=186 AND id BETWEEN 9001 AND 9047 FOR UPDATE;
IF n<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Hate layout count drift: grid'; END IF;
SELECT COUNT(*) INTO n FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='grid_entries' AND ENGINE='InnoDB';
IF n<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Hate layout engine drift: grid_entries'; END IF;
SELECT COUNT(*) INTO n FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='grid_entries';
IF n<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Hate layout trigger drift: grid_entries'; END IF;
SELECT COUNT(*) INTO n FROM `grid_entries` WHERE zoneid=186 AND gridid BETWEEN 9001 AND 9047 FOR UPDATE;
IF n<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Hate layout count drift: grid_entries'; END IF;
COMMIT;
END //
DELIMITER ;
